algorithms.pseudocode:
def sync(range, me, peer, depth=0):
    if me.hash(range) == peer.hash(range): return
    if depth == MAX_DEPTH:
        stream_diff(range, me, peer); return
    for child in split(range):
        sync(child, me, peer, depth + 1)

def phi(node, now):
    t = now - last_heartbeat[node]
    mean = intervals[node].mean()
    p_later = exp(-t / mean)          # exponential approximation
    return -log10(p_later)
